INSERT INTO `langinfo` VALUES (7077, 'NPCInfo.NPCName', 1, '活动管理员', 'Eventmanager', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7078, 'MagicInfo.Description', 1, '提高命中率的技能,级别越高就会越准确.', 'A skill that increases your accuracy. The skill becomes more effective as you train.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7079, 'MagicInfo.Description', 1, '可以提高使用药水的能力,随着修炼等级的提升增加恢复量.', 'You become adept at using recovery items. You may recover more depending upon the level of your training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7080, 'MagicInfo.Description', 1, '提高命中率和破坏力的技能,修炼等级越高,命中率也高并且会发挥很强的破坏力.', 'A skill that increases your accuracy and damage. The skill becomes more effective as you train.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7081, 'MagicInfo.Description', 1, '利用剑气对攻击范围外的敌人也照成伤害,根据技能等级提升增加伤害.(学习此技能的话 原有的御剑术,御剑术-强化,御剑术-奥义会被消除)', 'Attack enemies outside of the melee range using the energy of your weapon. The damage done increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7082, 'MagicInfo.Description', 1, '用快速挥动剑时产生的剑风攻击周围敌群(4个)的高级剑术,修炼等级越高,破坏力越大.', 'An ancient skill attack that hits 4 nearby enemies with the power of wind created from the swing of a weapon. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7083, 'MagicInfo.Description', 1, '是用肩部把等级低于自己的敌人撞开的武功,随修炼等级提升,增加撞开的距离和敌人的数量.', 'A shoulder blow to push away enemies of lower levels. As you train harder, you\'ll be able to push more enemies.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7084, 'MagicInfo.Description', 1, '聚集体内热气注入到武器而加强破坏力,修炼等级越高,破坏力越大.', 'Transfer your body\'s energy onto the weapon to increase its damage.  The damage bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7085, 'MagicInfo.Description', 1, '运气丹田喷向空中,在从半空落下攻击敌人的技能,修炼等级越高,破坏力越大.', 'Harness the body\'s energy to throw yourself into the enemies. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7086, 'MagicInfo.Description', 1, '用快速的剑法连续攻击两次的技能,修炼等级越高,破坏力越大.', 'A fast attack that deals 2 blows to the enemy. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7087, 'MagicInfo.Description', 1, '用剑光攻击包围自己的所有敌人的技能,修炼等级越高,破坏力越大.', 'Transfers your body\'s energy onto your weapon to deal damage to your enemies around you. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7088, 'MagicInfo.Description', 1, '与对方互相换位置的技能,修炼等级越高,成功率越高.', 'A skill that allows you to switch the location of you and your target. Its chance of success increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7089, 'MagicInfo.Description', 1, '降低自己的破坏力提高防御力和技能防御力的技能,随修炼等级提升,防御力和技能防御力的增加量和持续时间将增加.', 'Significantly increase your defense and magic resistance. Duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7090, 'MagicInfo.Description', 1, '将远处的敌人吸到自己跟前的技能,修炼等级越高,成功率越高.', 'A skill that pulls a distant target into melee range. Its success rate increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7091, 'MagicInfo.Description', 1, '降低自己的防御力暂时提高破坏力的技能,随修炼等级提升,破坏力和持续时间将增加.', 'Moderately increase your damage.  The damage bonus and duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7092, 'MagicInfo.Description', 1, '把剑气集中在刀尖,瞬间击退多数敌人.', 'A skill that deals damage to enemies by releasing the energy within your weapon as you thrust it into the ground.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7093, 'MagicInfo.Description', 1, '利用浑身之气,回避中毒及异常状态.', 'Uses your body\'s energy to avoid being poisoned, pushed back from enemy attacks, and any other harmful status effects.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7094, 'MagicInfo.Description', 1, '返回攻击者对您造成的伤害的百分比.', 'Returns a percentage of damage done to you back to the attacker.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7095, 'MagicInfo.Description', 1, '利用浑身之气减弱敌人的移动能力.', 'You slow your enemy\'s movement speed and attack speed using your body\'s energy.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7096, 'MagicInfo.Description', 1, '攻击周围多数人的技能, 随着修炼威力将变强. ', 'A skill that is most effective when used while surrounded by enemies. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7097, 'MagicInfo.Description', 1, '以浑身之气击退敌人的技能,被击中后一定时间内处于头晕状态.', 'Knock multiple enemies back with a chance to render the enemy unconscious. Effectiveness increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7098, 'MagicInfo.Description', 1, '一种比刀锋更强大的技能,它的伤害随着训练而增加.', 'A skill more powerful than the Bladestorm. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7099, 'MagicInfo.Description', 1, '火系列最基本的技能,修炼等级越高,威力越强.', 'The most basic Fire spell. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7100, 'MagicInfo.Description', 1, '雷系列最基本的技能,修炼等级越高,威力越强.', 'The most basic Lightning spell. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7101, 'MagicInfo.Description', 1, '冰系列的最基本技能,将敌人冻僵使对方行动变得缓慢,修炼等级越高,威力越强.', 'The most basic Ice spell that damages the enemy and slows its movement speed. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7102, 'MagicInfo.Description', 1, '风系列最基本的技能,有将敌人推开的效果.修炼等级越高,威力越强,成功率越高.', 'The most basic Wind spell that pushes away enemies. Its damage and chance to push away your enemy increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7103, 'MagicInfo.Description', 1, '可以将等级低于自己的敌人按一定几率推开的护身技能.修炼等级提升,推开的距离和成功率越高.', 'A defensive spell that allows you to push away enemies of lower level. This spell has a fixed chance for success. The range of the spell and chance of success increase with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7104, 'MagicInfo.Description', 1, '用强烈的电击麻痹敌人的灵魂,使之成为自己的帮手,修炼等级提升,持续时间和成功率越高.', 'A spell that knocks the enemy unconscious.  Your chance of success and duration of its effect increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7105, 'MagicInfo.Description', 1, '用强烈的技能贯通时空,随机移动到某一地点.修炼等级越高,成功率越高.', 'A spell that moves you to a random location. Your chance of success increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7106, 'MagicInfo.Description', 1, '火球术的强化技能,修炼等级越高,威力越强.', 'A spell that is more powerful than the Fireball. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7107, 'MagicInfo.Description', 1, '用雷攻击敌人的技能,修炼等级越高,威力越强.', 'A spell that creates Thunderbolts to strike down on your enemies. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7108, 'MagicInfo.Description', 1, '冰月神掌的强化技能,修炼等级越高,威力越强.', 'A spell that is more powerful than the Iceball. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7109, 'MagicInfo.Description', 1, '用龙卷风攻击一名敌人的技能,修炼等级越高,威力越强.', 'A Cyclone attack spell that damages a single enemy. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7110, 'MagicInfo.Description', 1, '施放强烈直线火焰攻击多数敌人的技能,修炼等级越高,威力越强.', 'A spell that shoots out line of fire along the ground, damaging all enemies caught within the fire. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7111, 'MagicInfo.Description', 1, '施放直线闪电攻击多数敌人的技能,修炼等级越高,威力越强.', 'A spell that shoots out a beam of lightning, damaging all enemies caught within the lightning. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7112, 'MagicInfo.Description', 1, '施放直线冰气攻击敌人的技能,还会一定时间内使敌人动作迟钝.修炼等级越高,威力越强.', 'A spell that erects shards of ice from the ground in a line, damaging all enemies in the path. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7113, 'MagicInfo.Description', 1, '施放直线风力攻击多数敌人的技能,修炼等级越高,威力越强.', 'A spell that allows you to harness the power of the winds and cause it to blow in front of the caster in a straight line. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7114, 'MagicInfo.Description', 1, '一定的时间内在指定地方点燃火焰连续攻击此处敌人的技能,修炼等级提升,持续时间和威力将增加.', 'A spell that creates a wall of fire in the shape of a cross damaging enemies over a period of time. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7115, 'MagicInfo.Description', 1, '是可以将死者系列的敌人一次性消灭的技能,修炼等级越高,成功率越高.', 'A spell that instantly kills undead enemies. Its chance of success increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7116, 'MagicInfo.Description', 1, '在一定空间内根据自己的意愿移动的技能,修炼等级越高,成功率越高.', 'A spell that harnesses the body\'s energy to move to a desired location. The chance of success increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7117, 'MagicInfo.Description', 1, '用魔力在自己周围形成保护膜,在一定时间内减少伤害的技能.修炼等级越高,持续时间越长.', 'Creates a magical shield around the caster that reduces the damage taken for a set period of time. The duration of the spell increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7118, 'MagicInfo.Description', 1, '攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 'A spell that deals fire damage to all enemies within a fixed area(3x3) of choice. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7119, 'MagicInfo.Description', 1, '用雷攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 'A spell that deals lightning damage to all enemies within a fixed area(3x3) of choice. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7120, 'MagicInfo.Description', 1, '用寒气攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 'A spell that deals ice damage to all enemies within a fixed area(3x3) of choice with ice. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7121, 'MagicInfo.Description', 1, '用龙卷风攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 'A spell that attacks all enemies within a fixed area(3x3) of choice with a cyclone. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7122, 'MagicInfo.Description', 1, '施放三股寒气给大范围内敌人造成伤害,并且使对方行动变缓的技能.修炼等级越高,威力越强.', 'A spell that erects 3 lines of ice shards from the ground in three directions to damage and slow the enemies. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7123, 'MagicInfo.Description', 1, '可以对大范围的(9*9)敌人进行雷电攻击,但距离越远杀伤力越小.修炼等级越高,威力越强.', 'A spell that inflicts lightning damage to enemies in a large area(9x9), but the damage inflicted decreases as the lightning spreads out from its attack point. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7124, 'MagicInfo.Description', 1, '可以给一定区域内多数敌人带来火焰伤害.修炼等级越高,威力越强,可以攻击更多敌人.', 'A spell that damages enemies within a set range. Its damage and the number of enemies affected increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7125, 'MagicInfo.Description', 1, '在一定时间内削弱大量体力而提高魔力的技能,修炼等级越高,单次提高魔力幅度越大.', 'A spell that sacrifices your HP to increase your Spell Power for a fixed period of time.  The Spell Power bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7126, 'MagicInfo.Description', 1, '在(3*3)范围内形成旋风的武功,随修炼等级提升,旋风墙的破坏力和持续时间会增加.', 'A spell that creates a Cyclone to attack enemies in a set area(3x3) for a set period of time. Its damage and duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7127, 'MagicInfo.Description', 1, '自动向对自己发动攻击的敌人进行闪电攻击.', 'The enemy that attacks you gets struck by lightning each time you take damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7128, 'MagicInfo.Description', 1, '施放时在一定范围内降闪电, 但闪电的掉落位置无法控制,攻击会造成非常大的伤害.', 'When cast, lightning strikes down randomly in a fixed area, dealing massive damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7129, 'MagicInfo.Description', 1, '直线攻击多数敌人的魔法, 随着使用的魔石种类, 技能元素将有所改变.', 'Concentrate your body\'s energy to shoot at a single target. The property of the energy depends on the equipped dark stone.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7130, 'MagicInfo.Description', 1, '攻击单个敌人的魔法, 随着使用的魔石种类, 技能元素将有所改变.', 'You condense your body\'s energy and burst it in a line, dealing damage to anyone caught in its path. The energy does not have any properties unless used with a dark stone.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7131, 'MagicInfo.Description', 1, '在自己周围产生保护膜的魔法, 一定时间内可以回避敌人的攻击. ', 'Creates a powerful barrier around you with the power of the wind, reducing the damage done to you for a set time.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7132, 'MagicInfo.Description', 1, '凝血离魂的加强技能, 更稳定地削弱大量体力来提高魔法的技能. ', 'Reduces the chance of decreasing your health points and increases your spell power.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7133, 'MagicInfo.Description', 1, '攻击一定范围内的所有敌人, 随着使用的魔石种类, 技能元素将有所改变. ', 'Attacks all enemies in a fixed area(3x3). It does not have a property, however with the use of a dark stone, its property changes depending on the dark stone.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7134, 'MagicInfo.Description', 1, '指定目标, 一定时间内快又强烈施加魔法, 随着使用的魔石种类, 技能元素将有所改变. ', 'Harness your body\'s energy to create a powerful cyclone of energy to attack your enemies. The property of this ability depends on the dark stone used, otherwise, it does not have a property.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7135, 'MagicInfo.Description', 1, '通过运气来治疗自己或他人的技能,修炼等级越高,可以恢复的量越多.', 'A spell to heal yourself or others by using your body\'s energy. The amount healed increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7136, 'MagicInfo.Description', 1, '提高自身命中率的技能,修炼等级越高,命中率越高.', 'A skill that increases your Accuracy. The Accuracy bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7137, 'MagicInfo.Description', 1, '根据毒粉的能力来降低防御力或持续减少一定量的体力,修炼等级越高,持续时间越长.', 'A spell that decreases your enemy\'s defense or strength, depending on the Poison Powder, for a set period of time. The effect\'s duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7138, 'MagicInfo.Description', 1, '在护身符中注入带有爆发力的道力使用的技能,修炼等级越高,威力越强.', 'Throws an explosive talisman at the enemy. Its power is increased when used with a Dark Talisman.  Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7139, 'MagicInfo.Description', 1, '将神圣气息凝聚在手中攻击敌人,佩戴神圣护身符使用威力更强.修炼等级越高,威力越强.', 'Harness the holy energy in your hands to throw at your enemy. Its power is increased when used with a Holy Talisman. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7140, 'MagicInfo.Description', 1, '可以暂时在敌人面前隐身的技能,修炼等级越高,隐身效果持续时间越长.', 'Temporarily hide yourself, vanishing from your enemy\'s sight.  Its duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7141, 'MagicInfo.Description', 1, '通过运气,提高对外部技能攻击防御的技能,修炼等级越高,防御力越强,持续时间越长.', 'Using your body\'s energy, you increase your resistance to magic. The resistance bonus and duration of the effect increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7142, 'MagicInfo.Description', 1, '升级版的隐身术,可以使一定区域内(3*3)的人全部隐身.修炼等级越高,隐身效果持续时间越长.', 'An advanced invisibility technique that allows you to hide everyone in a fixed area(3x3). Its duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7143, 'MagicInfo.Description', 1, '比月魂断玉更加强大的技能,修炼等级越高越强大.如果使用神圣护身符,威力更大.', 'A spell that is more powerful than the Holy Strike. Its damage increases with training, and even more so if used with a Holy Talisman.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7144, 'MagicInfo.Description', 1, '通过运气,短时间提高对外部物理攻击的防御力,修炼等级越高,防御力提高持续时间越长.', 'Using your body\'s energy, you increase your defense against physical attacks. Its duration and defense bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7145, 'MagicInfo.Description', 1, '使用护身符,在一定的空间范围内使用道力锁住其中敌人的技能,修炼等级越高,效果持续时间越长.', 'A spell that uses a talisman to trap enemies in a small area. Its duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7146, 'MagicInfo.Description', 1, '用脚大力推开对方的技能,修炼等级越高,可以推开的概率和杀伤力越大.', 'Kick your enemies away from you. Its damage and chance to push back your enemies increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7147, 'MagicInfo.Description', 1, '使用护身符提高自己或他人的技能攻击力,或用元素护身符在一定时间内增加攻击元素的技能.修炼等级越高,效果持续时间越长.', 'Use a talisman to increase the spell power of yourself or others, or use the elemental talisman to increase the attack elements.  Its duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7148, 'MagicInfo.Description', 1, '可以治疗一定区域内(3*3)的人,修炼等级越高,体力恢复量就越多.', 'A spell that heals multiple people within a fixed area(5x5) tiles at the same time. The amount healed increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7149, 'MagicInfo.Description', 1, '通过运气,暂时提高物理攻击力,修炼等级提升,攻击力增加量和持续时间也相应增多加长.', 'Use your body\'s energy to increase the attack of yourself or others. Its duration and damage bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7150, 'MagicInfo.Description', 1, '使用灵魂护身符让死人复活的技能,修炼等级越高,可以使死人复活的概率越高.', 'Revive the dead by using a Talisman of Soul. The chance to revive increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7151, 'MagicInfo.Description', 1, '可以消除技能和物理攻击效果,不仅可以取消中毒麻痹,还可以取消能力值提高效果.', 'Removes all magical and skill effects. Not only does it remove poison and paralysis, but any ability enhancement effects also.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7152, 'MagicInfo.Description', 1, '不仅对怪物隐身,对他人也可以隐身,修炼等级越高,隐身持续时间越长.', 'You become invisible to monsters and other players. Its duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7153, 'MagicInfo.Description', 1, '调出体内潜在的力量,受到超过体力值的伤害时,可以抵御进攻并恢复少量体力值.', 'Draws upon your remaining bit of energy to block an enemy attack that would otherwise kill you. Also restores a small amount of HP.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7154, 'MagicInfo.Description', 1, '每使用一次治愈术时,会恢复较多的HP.角色等级和灵魂系HP的恢复量.', 'Increases the amount healed by your next healing spell. The bonus amount healed depends on your level and training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7155, 'MagicInfo.Description', 1, '把敌人受到的部分伤害值转化为HP,并加到自己或同伴身上.', 'Use your body\'s energy to increase the Life stealing of yourself or others. Its duration and Life steal bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7156, 'MagicInfo.Description', 1, '灵魂火符的加强武功,每次发出3张护身符给予敌人更大的伤害.使用暗黑护身符会提高武功的威力.', 'An upgraded version of the Explosive Talisman, used to throw 3 explosive talismans to deal massive amounts of damage. Its damage increases if used with Dark Talisman.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7157, 'MagicInfo.Description', 1, '给一定范围内的怪物施毒.', 'Augment\'s Poison dust, When casting poison dust, there is a chance it will effect nearby enemies.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7158, 'MagicInfo.Description', 1, '受到攻击的敌人变成稻草人,攻击稻草人所产生的部分伤害会转到敌人身上.', 'When you attack an enemy, you create a dummy that resembles your target. damage done to this dummy will damage your enemy for a set amount.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7159, 'MagicInfo.Description', 1, '用腿攻击敌人时,被击中的敌人不会受到伤害.但周围的敌人会受到较大的伤害或被击退.', 'When you kick an enemy, your target enemy remains in place, but the surrounding enemies gets pushed back or receives a large amount of damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7160, 'MagicInfo.Description', 1, '提高防御力的技能, 一定时间内可抵抗敌人的魔法及物理攻击.', 'A spell that increases your defense against physical attacks and your resistance against magic attacks for a set period of time. Its duration and defense/resistance bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7161, 'MagicInfo.Description', 1, '妙影无踪的加强技能, 隐藏自己以及一定范围内多数人的技能.', 'An improved version of Greater Invisibility where you make people in a fixed area(3x3) invisible.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7162, 'MagicInfo.Description', 1, '月魂灵波与灭魂火符的加强技能. ', 'Combines the advantages of the Improved Holy Strike and Improved Explosive Talisman skills. Its power and property depends on the type of talisman used.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7163, 'MagicInfo.Description', 1, '提升自身敏捷(回避率)的技能,修炼等级越高回避率越高.', 'Increases your Agility. Your Agility bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7164, 'MagicInfo.Description', 1, '提升自身准确(命中率)的技能,修炼等级越高越准确命中敌人.', 'Increases your Accuracy. Your accuracy bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7165, 'MagicInfo.Description', 1, '提升准确度和最小物理伤害值,修炼等级越高提升的准确度和最小物理伤害值越高.', 'Increases your accuracy and minimum damage. Accuracy and minimum damage bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7166, 'MagicInfo.Description', 1, '在自己周围释放鬼雾,提升该范围内对物理攻击的回避率.', 'Creates a cloud of poison around you, increasing your dodge rate while standing in the clouds.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7167, 'MagicInfo.Description', 1, '将最大魔力的一定 %转换为物理伤害,给对方造成额外伤害.', 'Converts a percentage of your max mana into additional physical damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7168, 'MagicInfo.Description', 1, '采取隐身状态,期间会持续消耗体力,并可以移动,攻击,使用道具.隐身状态中被攻击或攻击,使用道具时将解除隐身状态,修炼级别越高,隐身期间消耗的体力越少.', 'You become invisible. While in this state, you can move, attack, and use items at the expense of your HP.  You become visible when you attack or use an item. The amount of HP used decreases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7169, 'MagicInfo.Description', 1, '将最大魔力的一定 %转换为物理伤害,给对方造成额外伤害.当对方受到盛开伤害时使用该技能,可再增加伤害.', 'Converts a percentage of your max mana into additional physical damage. Enemies damaged by Full Bloom receives additional damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7170, 'MagicInfo.Description', 1, '在刺杀激活的状态下,用普通攻击命中怪物时,有一定概率产生增加伤害,修炼级别越高概率和伤害值也越高.', 'You have chance to deal additional damage when attacking monsters. Its chance and damage bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7171, 'MagicInfo.Description', 1, '在黑暗中召唤亡者,一定时间内绑住对方让其消耗魔力,修炼等级越高锁住对方的时间也越长.', 'Summons a creature of darkness that prevents the enemies from moving and steals mana for a set period of time. Its duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7172, 'MagicInfo.Description', 1, '将最大魔力的一定 %转换为物理伤害,给对方造成额外伤害.当对方受到白莲伤害时使用该技能,可再增加伤害.', 'Converts a percentage of your max mana into additional physical damage. Enemies damaged by White Lotus receives additional damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7173, 'MagicInfo.Description', 1, '从野火中召唤罗刹鬼给对方造成火焰伤害,并一定时间内持续给予火焰伤害.修炼等级越高伤害值越高.', 'Summons a demon from the Flames of Fire and Brimstone to inflict fire damage to an opponent and additional fire damage over time. Its damage increases with time.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7174, 'MagicInfo.Description', 1, '潜行时,根据修炼等级,使施展者的体力消耗减少一定量%.修炼等级越高,体力消耗量越少.', 'When cloaking, your HP consumption is reduced by a fixed percentage depending on the level of your training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7175, 'MagicInfo.Description', 1, '在隐身状态下攻击对方,造成一定伤害,在一定时间内使对方的移动速度减少50%.技能施展后隐身状态解除.修炼等级越高,效果的持续时间越长.', 'This ability brings you out of the cloaking state. Its effect and duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7176, 'MagicInfo.Description', 1, '将最大魔力的一定 %转换为物理伤害,给对方造成增加伤害. 当对方受到红莲伤害时使用该技能,可再增加伤害', 'Converts a percentage of your max mana into additional physical damage. Enemies damaged by Red Lotus receives additional damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7177, 'MagicInfo.Description', 1, '召唤亡灵形象的木偶后自己则隐身,木偶被攻击时附近的敌人会受火焰伤害,战斗中可使用该技能,修炼级别越高可召唤越多的木偶.', 'Trick your enemies to believe you\'re dead while you summon a puppet and become invisible. The summoned puppet deals fire damage when attacked. This can be used while in combat and number of puppets summoned increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7178, 'MagicInfo.Description', 1, '隐身状态下消耗自己最大体力的一定 %给对方造成强力的物理伤害.无论是否命中对方,使用后10秒内无法使用恢复类道具.', 'While in an invisible state, you deal massive damage to your enemy by spending a percentage of your total HP. You cannot use a recovery item for 10 seconds after the attack.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7179, 'MagicInfo.Description', 1, '使受到束缚效果的对象无法使用技能,从对象身上吸取魔力,按一定%转换为施展者的魔力.修炼等级越高,获得的魔力量越多.', 'Your opponent becomes dominated by the Wraith Grip spell effect and is unable to use any Mu-Gong. You also receive a percentage of your target\'s Mana. The amount of Mana received increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7180, 'MagicInfo.Description', 1, '在暗杀激活的状态下,普通攻击命中对方玩家时,有一定几率造成额外伤害.修炼等级越高,发动概率越高.', 'The attacker receives greater amount of additional damage. The chance of dealing additional damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7181, 'MagicInfo.Description', 1, '施展潜行时,有一定几率使隐身状态下的移动速度提高2倍.修炼等级越高,启动效果概率越高.', 'When Cloaking, you have a chance to increase your movement speed by 100%. This chance increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7182, 'MagicInfo.Description', 1, '根据施展者装备的魔石,变更使用亡灵替身召唤的木偶属性.在装备魔石的状态下使用亡灵替身,魔石的持久会减少一定值.修炼等级越高.魔石对木偶产生的效果越好.', 'The effect of your puppet summoned by the Summon Puppet spell changes depending on your equipped dark stone. The charges of the dark stone decreases when you use the Summon Puppet spell with the dark stone equipped.  The effect of your puppet increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7183, 'MagicInfo.Description', 1, '非战斗状态下增加体力和魔力的恢复量,修炼级别越高增加的恢复量也越高.', 'Your HP and Mana regeneration rate increases while not in combat. The regeneration rate bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7184, 'MagicInfo.Description', 1, '提高孽报的命中率,用孽报攻击时忽视一定量对方的物理防御.修炼级别越高孽报的命中率和忽视对方的防御程度也越高.', 'Increases the accuracy of Karma and allows it to ignore your opponent\'s defense by a set amount. Accuracy and defense ignored increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7185, 'MagicInfo.Description', 1, '改变当前使用暗杀和刺杀模式.此技能无法继续修炼.', 'Removed from game', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7186, 'MagicInfo.Description', 1, '施展孽报时,使施展者的体力消耗根据修炼等级减少一定%.修炼等级越高,施展时体力消耗量越少.', 'When performing Karma, your HP consumption is reduced by a set percentage, depending on your level of training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7187, 'MagicInfo.Description', 1, '用普通攻击给对象造成伤害时,有一定几率给靠近施展者的最多4个对象造成物理伤害.该效果在给对象造成伤害时有一定几率发动.修炼等级越高,伤害量越高.', 'Deals physical damage as fire damage to 4 enemies around you. The effect is triggered by chance when you deal damage to an enemy. Amount of damage dealt increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7188, 'MagicInfo.Description', 1, '使盛开、白莲、红莲和月季系列的伤害增加一定倍数.修炼等级越高,效果越好.', 'Increases your Life Stealing. Its effects increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7189, 'MagicInfo.Description', 1, '激活此技能60秒里[孽报]造成额外的魔法伤害,伤害随等级程度而提升', 'When activated, your next Flash of Light used within 60 seconds deals multiple attacks as additional magic damage. Its damage increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7190, 'MagicInfo.Description', 1, '瞬间移动到对象附近,造成伤害,并有一定几率使对象眩晕.修炼等级越高,使对象眩晕的几率越高.', 'Damage your opponent after you teleport and also has a chance to stun your opponent. Its chance to stun increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7191, 'MagicInfo.Description', 1, '在活动状态下，你的最大法力值的一定百分比将转化为你的生命值,提供的生命值等于所使用的法力值的2倍.它的效果随着训练而增强.', 'While active, a set percentage of your maximum Mana is converted to your HP, providing HP equal to 2 times the Mana used.  Its effect increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7192, 'MagicInfo.Description', 1, '消耗体力和魔力,在自身周围展开锁链阵,给对象造成物理伤害并将其击退.击退效果对比施展者高6级以上的对象无效.修炼等级越高,伤害越高.', 'Inflicts physical damage and pushes nearby enemies back. The push back effect does not work on enemies 8 levels higher than you. Damage dealt increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7193, 'MagicInfo.Description', 1, '转换暗杀和刺杀激活的状态下,最大物理防御和最大技能防御增加一定数值.修炼等级越高,破坏值越高.', 'Increases your Max AC. Its effects increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7194, 'MagicInfo.Description', 1, '转换暗杀和刺杀激活的状态下,最小破坏和最大破坏增加一定数值.修炼等级越高,增加的防御值越多.', 'Increases your Max MR. Its effects increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7195, 'MagicInfo.Description', 1, '使对象陷入深深的绝望和黑暗之中.被效果支配的对象的视野减小,命中率减少一定%.在隐身状态下使用,隐身状态不会解除.一次只对一个对象有效.修炼等级越高,对象命中率的减少量越多.', 'You shroud your opponent in darkness, reducing their sight and accuracy by a set percentage. The duration increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7196, 'MagicInfo.Description', 1, '消耗施展者最大魔力的一定%,对前方2格内的所有对象加以强力一击.施展者获得心击一转效果的状态下,根据心击一转的重叠次数,造成额外伤害.在获得心击一转效果的状态下使用,心击一转的重叠次数将消耗掉1次.修炼等级越高,伤害量越高.', 'You deal massive damage to all enemies within 2 tiles.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7197, 'MagicInfo.Description', 1, '在潜行状态下做出解除隐身的动作时,消耗心击一转重叠次数1次,有一定几率维持隐身状态.在没有获得心击一转效果时无法使用.修炼等级越高,维持隐身状态的几率越高.', 'Description : When you perform an action that causes you to break cloak,  you\'re able prevent it by spending the charged “The New Beginning”. Cannot be used without the The New Beginning effect. The chance of remaining in the cloaking state increases with', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7198, 'MagicInfo.Description', 1, '效果持续期间,有一定几率完全回避掉攻击施展者的对象的攻击,和攻击的属性无关.修炼等级越高,完全回避的几率越高.', 'You have a chance to dodge your opponent\'s Elemental attack. Its chance increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7199, 'MagicInfo.Description', 1, '效果持续期间,施展者的最小物理防御力和最大物理防御力提高.修炼等级越高,效果越好.', 'Your Minimum defense increases by a percentage of your Maximum defense , and your Maximum defense is decreased by a set percentage. Its effects increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7200, 'MagicInfo.Description', 1, '增加爆炸护身符(和强化)，当施放爆炸护身符时，有机会影响附近的敌人。', 'Augments Explosive Talisman (and Improved), When casting Explosive Talisman, there is a chance it will effect nearby enemies.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7201, 'MagicInfo.Description', 1, '增加邪恶杀戮者(更大)，当施放邪恶杀戮者时，有机会影响附近的敌人。', 'Augments  Evil Slayer (and Greater), When casting  Evil Slayer, there is a chance it will effect nearby enemies.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7202, 'MagicInfo.Description', 1, '强化净化，当施法净化时，有机会影响附近的目标。', 'Augments Purification, When casting Purification, there is a chance it will effect nearby targets.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7203, 'MagicInfo.Description', 1, '强化复活，当施放复活时，有机会影响附近的盟友。', 'Augments Resurrection, When casting Resurrection, there is a chance it will effect nearby Allies.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7204, 'MagicInfo.Description', 1, '把使用焰魔召唤术召唤的宝宝强制性解放的技能,宝宝的等级和体力越高,给对方的伤害越大.', 'Cause your summoned creature to explode, inflicting damage to nearby enemies. damage inflicted depends on the level of your summoned creature.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7205, 'MagicInfo.Description', 1, '牺牲自身的破坏力,提高属下怪物一定时间内的攻击力,修炼等级越高,属下怪物攻击力提高量越大.', 'Increases the damage of your summoned creature by sacrificing your own damage. The damage bonus of your summoned creature increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7206, 'MagicInfo.Description', 1, '在护身符中注入神气,召唤具有强大力量的灵魂为自己所用,修炼等级越高,可以召唤越强大的灵魂.', 'By inserting your body\'s energy into the talisman, you summon a powerful spirit to fight for you. The strength of your summoned spirit increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7207, 'MagicInfo.Description', 1, '产生与自己同样的幻影,幻影可以施放与自己同样的魔法攻击.使用此技能必须要持有魔法矿石.', 'The spell creates an illusion of yourself which has the same magic attack abilities. You must have a dark ore to cast this spell.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7208, 'MagicInfo.Description', 1, '在护身符中注入神气,召唤带有强大力量的灵魂为自己所用,已经召唤了神兽或骷髅的状态下也可以使用.修炼等级越高,可以召唤越强大的灵魂.', 'By focusing your body\'s energy onto a talisman, you summon a mighty spirit to fight for you. You may use this Mu-Gong even if you have already summoned a Holy Beast or a Skeleton. The strength of the mighty spirit increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7209, 'MagicInfo.Description', 1, '在护身符里注入神气,召唤神圣动物的技能,修炼等级越高,可以召唤越强的神兽.', 'By focusing your body\'s energy onto a talisman, you call upon the Holy Beasts to fight for you. The strength of the Holy Beast increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7210, 'MagicInfo.Description', 1, '解开并召唤被封印的焰魔,它的邪恶气息仍未消失.修炼级别越高,召唤的焰魔越强.', 'By inserting your body\'s energy into the talisman, you summon a infernal creature to fight for you. The power of your summoned creature increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7211, 'MagicInfo.Description', 1, '您将更加熟练地使用恢复项,根据你的训练水平,你可以恢复得更多.', 'You become further adept at using recovery items. You may recover more depending upon the level of your training. Works with Regular Potion Mastery.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7212, 'MagicInfo.Description', 1, '增加你的偷袭技巧,它的效果随着修炼等级而增强.', 'Increases your Life Stealing. Its effects increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7213, 'MagicInfo.Description', 1, '被动咒语,增加你的法术力量,随着修炼等级,法术力量加成会增加.', 'Passive Spell. Increase your Spell Power.  The Spell Power bonus increases with training.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7214, 'MagicInfo.Description', 1, '嘲讽,使一定范围的敌人,召回到你的附近.', 'Taunt, call enemies within a certain range back to your vicinity.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7215, 'MagicInfo.Description', 1, '技能的持续时间里,可有几率将敌人的攻击变成冰系伤害转移给对方,且降低移动攻击速度.', 'During the duration of the skill, there is a chance that the enemy\'s attack will be turned into ice damage and transferred to the opponent, and the movement attack speed will be reduced.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7216, 'MagicInfo.Description', 1, '通过灵魂之力,给一定范围内的敌人释放来之地狱的瘟疫,持续给目标伤害,瘟疫的伤害和持续时间,与修炼等级相关.', 'Through the power of the soul, the plague of the hell is released to the enemies within a certain range, and the target is continuously damaged.The damage and duration of the plague are related to the level of cultivation.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7217, 'MagicInfo.Description', 1, '生命到达底限时自动触发,发挥超越极限的能力.随技能等级的提升,触发几率和持续时间也随之增加.', 'It is automatically triggered when the life limit is reached, and the ability to exceed the limit is exerted. As the skill level increases, the trigger probability and duration also increase.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7218, 'MagicInfo.Description', 1, '强力的锤击,攻击指定位置,这是范围技能,可对该区域敌人造成伤害且击倒对手,有一定几率附带晕眩效果.', 'A powerful hammer blow to attack the specified location.This is an area skill, which can cause damage to the enemy in the area and knock down the opponent. There is a certain chance that it will be accompanied by a stun effect.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7219, 'MagicInfo.Description', 1, '来自地狱不灭死神的契约，你与你的属下形成了灵魂契约,你每次施法技能,你的属下将瞬间恢复生命,属下生命按百分比恢复,恢复加成随着修炼等级而加强.', 'From the contract of the immortal god of hell, you have formed a soul contract with your subordinates. Every time you cast a spell, your subordinates will instantly restore life, and the subordinates\' health will be restored by a percentage, and the restoration bonus will increase with the level of cultivation.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7220, 'MagicInfo.Description', 1, '召唤巨大的火球从天而降,攻击点造成强力的范围伤害且再攻击点地域留下的火墙造成2次伤害.', 'Summon a huge fireball to drop from the sky, the attack point will cause powerful area damage and the fire wall left by the attack point area will cause 2 damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7221, 'MagicInfo.Description', 1, '增加分身的数量，佩戴不同的魔石攻击属性不同.', 'Increase the number of clones and wear different magic stones with different attack attributes.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7222, 'MagicInfo.Description', 1, '一定时间内无视伤害.', 'Ignore the damage for a certain period of time.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7223, 'MagicInfo.Description', 1, '强力的气劲融入剑技之中发射出去,直线攻击技能,随修炼技能等级的提升,伤害增加,CD时间减短.', 'The powerful vigor is integrated into the sword skill and launched, the straight line attack skill, as the training skill level increases, the damage increases, and the CD time decreases.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7224, 'MagicInfo.Description', 1, '折损对手意志,让对手陷入虚弱状态.中招后对手的攻击力,移动能力减少,体力无法恢复.', 'The opponent\'s will is compromised and the opponent falls into a weak state. After the attack, the opponent\'s attack power and mobility are reduced, and the physical strength cannot be recovered.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7225, 'MagicInfo.Description', 1, '掌控黑暗力量凝造一个(7*7)的鬼阵,向对手植入妄想造成敌人的苦痛和恐惧,中招后,技能伤害之后还有追加的2次伤害加成.随技能等级的提升,持续时间和最小伤害也随之增加.', 'Control the dark power to condense a (7*7) ghost formation, implant delusions into the opponent to cause the enemy\'s pain and fear. After the attack, there will be an additional 2 damage bonus after the skill damage. With the increase of skill level, The duration and minimum damage also increase.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7226, 'MagicInfo.Description', 1, '魔法力量形成的保护盾.本武功使用后无法释放魔法盾,技能等级提升后保护盾也随之增强.', 'A protective shield formed by magical power. The magic shield cannot be released after the use of this martial arts, and the protective shield will increase as the skill level increases.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7227, 'MagicInfo.Description', 1, '指定方向内的直线攻击,按下技能按键后持续释放,对敌人有持续的钝化效果,如果在钝化效果下再受到该技能的伤害,僵陷入石化状态.', 'A straight line attack in the specified direction will be continuously released after pressing the skill button, and it will have a continuous passivation effect on the enemy.If it is damaged by the skill under the passivation effect, it will become petrified.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7228, 'MagicInfo.Description', 1, '召唤锐利的冰雨打击对手,在冰雨打击范围内滞留或者持续遭受冰雨攻击有一定几率被冰冻.（冰冻状态下无法移动和攻击,同样的也不受伤害）', 'Summon sharp icy rain to strike opponents, stay within the icy rain strike range or continue to suffer from icy rain attacks, there is a certain chance of being frozen. (You cannot move and attack in the frozen state, and the same is not hurt)', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7229, 'MagicInfo.Description', 1, '战士内功1级,瞬间移动至对手身边强推对手.', 'The fighter\'s internal strength is level 1, instantly moving to the opponent\'s side and pushing the opponent.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7230, 'MagicInfo.Description', 1, '战士内功2级,强推两次对手.', 'The fighter\'s internal strength is level 2, forcibly pushing the opponent twice.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7231, 'MagicInfo.Description', 1, '战士内功3级,召唤巨剑飞向地面.', 'The warrior\'s internal strength is level 3, and he summons the giant sword to fly to the ground.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7232, 'MagicInfo.Description', 1, '战士内功4级,地面伸出数把剑向周围的敌人攻击造成伤害.', 'The warrior\'s internal strength is level 4, and several swords are extended from the ground to attack the surrounding enemies and cause damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7233, 'MagicInfo.Description', 1, '法师内功1级,召唤强力的冰元素,冰冻范围里的对手.', 'The mage\'s internal strength is level 1, summons powerful ice elements, and opponents in the freezing range.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7234, 'MagicInfo.Description', 1, '法师内功2级,召唤小型水龙,向对手施行强力打击.', 'The mage\'s internal strength is level 2 and summons small water dragons to perform powerful blows on opponents.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7235, 'MagicInfo.Description', 1, '法师内功3级,召唤冰和风元素对一定范围的对手造成伤害.', 'The mage\'s internal strength is level 3, summoning ice and wind elements to cause damage to a certain range of opponents.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7236, 'MagicInfo.Description', 1, '法师内功4级,在风冰元素中心召唤巨龙施加范围伤害.', 'The mage\'s internal strength is level 4, summons a dragon in the center of the wind and ice element to inflict area damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7237, 'MagicInfo.Description', 1, '道士内功1级,束缚而且伤害对手.', 'Taoist internal strength is level 1, restraining and hurting opponents.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7238, 'MagicInfo.Description', 1, '道士内功2级,对被束缚的对手释放强力的雷电伤害.', 'Taoist internal strength level 2 releases powerful lightning damage to the restrained opponent.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7239, 'MagicInfo.Description', 1, '道士内功3级,从天空召唤强力的雷电,大面积伤害.', 'Taoist internal strength level 3, summons powerful thunder and lightning from the sky, and damages a large area.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7240, 'MagicInfo.Description', 1, '道士内功4级,利用隐没在云中的毒来攻击对手.', 'The Taoist internal strength is level 4, using the poison hidden in the cloud to attack the opponent.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7241, 'MagicInfo.Description', 1, '刺客内功1级,操纵数把附加了火焰的短剑飞向对手,造成伤害.', 'Assassin\'s internal skill level 1, manipulates several short swords with flames to fly towards the opponent, causing damage.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7242, 'MagicInfo.Description', 1, '刺客内功2级,转动起连带着尖锐刀刃的锁琏,给予对手致命打击.', 'The assassin\'s internal skill level 2 turned the lock with a sharp blade to inflict a fatal blow on the opponent.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7243, 'MagicInfo.Description', 1, '刺客内功3级,尖锐的刀刃和无数的锁琏攻击范围内的复数敌人.', 'Assassin\'s internal skill level 3, sharp blades and countless locks attack multiple enemies within the range.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7244, 'MagicInfo.Description', 1, '刺客4级内功,无数的小短剑如散花一般扩散开来打击对手.', 'Assassin\'s level 4 internal strength, countless small daggers spread like scattered flowers to strike opponents.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7245, 'MagicInfo.Description', 1, '增加自身物理攻击的暴击率.', 'Increase the critical strike rate of your own physical attacks.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7246, 'MagicInfo.Description', 1, '让敌人如深陷地狱般的剑飞向地面衍生出业火陷,持续15秒,(3*3)范围内造成伤害.随技能等级提升增加伤害,技能4级后,可有3次伤害.', 'Let the enemy\'s sword fly to the ground like a deep hell to generate a karmic fire, which lasts for 15 seconds, causing damage within a (3*3) range. The damage increases as the skill level increases. After the skill level 4, there can be 3 damages.', 0, '2024-03-06 17:18:26.000000');
INSERT INTO `langinfo` VALUES (7247, 'MagicInfo.Description', 1, '以释放者中心使大范围的复数敌人3秒内无法移动且每秒造成一定量得伤害.', 'Centering on the releaser makes multiple enemies in a large area unable to move for 3 seconds and deals a certain amount of damage every second.', 0, '2024-03-06 17:18:26.000000');
