INSERT INTO `magicinfo` VALUES (1, '火球术', 201, 1, 4, 1, 0, 6, 10, 0, 4, 3, 1, 7, 9, 11, 100, 200, 300, 50, '火系列最基本的技能,修炼等级越高,威力越强.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (2, '治愈术', 300, 2, 8, 1, 2, 11, 15, 0, 0, 7, 2, 7, 9, 11, 100, 200, 300, 40, '通过运气来治疗自己或他人的技能,修炼等级越高,可以恢复的量越多.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (3, '基本剑术', 100, 0, 2, 2, 4, 10, 10, 0, 0, 0, 0, 7, 9, 11, 100, 200, 300, 0, '提高命中率的技能,级别越高就会越准确.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (4, '精神力战法', 301, 2, 11, 2, 6, 9, 9, 0, 0, 0, 0, 8, 10, 12, 100, 200, 300, 0, '提高自身命中率的技能,修炼等级越高,命中率越高.', 246, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (5, '大火球', 208, 1, 4, 1, 8, 15, 19, 7, 11, 6, 6, 15, 17, 19, 400, 500, 600, 70, '火球术的强化技能,修炼等级越高,威力越强.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (6, '施毒术', 302, 2, 9, 1, 10, 25, 55, 15, 25, 10, 5, 12, 14, 16, 200, 300, 400, 60, '根据毒粉的能力来降低防御力或持续减少一定量的体力,修炼等级越高,持续时间越长.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (7, '攻杀剑术', 102, 0, 2, 2, 12, 7, 7, 8, 8, 0, 0, 14, 16, 18, 300, 400, 500, 0, '提高命中率和破坏力的技能,修炼等级越高,命中率也高并且会发挥很强的破坏力.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (8, '抗拒火环', 205, 1, 7, 1, 14, 3, 3, 2, 3, 8, 1, 12, 14, 16, 200, 300, 400, 60, '可以将等级低于自己的敌人按一定几率推开的护身技能.修炼等级提升,推开的距离和成功率越高.', 246, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (9, '地狱火', 212, 1, 4, 1, 16, 14, 18, 12, 16, 11, 15, 20, 22, 24, 500, 600, 700, 80, '施放强烈直线火焰攻击多数敌人的技能,修炼等级越高,威力越强.', 126, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (10, '疾光电影', 213, 1, 6, 1, 18, 14, 14, 12, 16, 12, 15, 21, 23, 25, 500, 600, 700, 80, '施放直线闪电攻击多数敌人的技能,修炼等级越高,威力越强.', 126, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (11, '雷电术', 209, 1, 6, 1, 20, 15, 19, 7, 11, 7, 6, 16, 18, 20, 400, 500, 600, 80, '用雷攻击敌人的技能,修炼等级越高,威力越强.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (12, '刺杀剑术', 103, 0, 3, 3, 22, 20, 20, 30, 30, 0, 0, 19, 21, 23, 400, 500, 600, 0, '利用剑气对攻击范围外的敌人也照成伤害,根据技能等级提升增加伤害.', 5, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (13, '灵魂火符', 303, 2, 9, 1, 24, 6, 10, 3, 3, 6, 3, 13, 15, 17, 200, 300, 400, 50, '在护身符中注入带有爆发力的道力使用的技能,修炼等级越高,威力越强.', 186, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (14, '幽灵盾', 306, 2, 9, 1, 26, 40, 120, 30, 50, 10, 5, 21, 23, 25, 500, 600, 700, 70, '通过运气,提高对外部技能攻击防御的技能,修炼等级越高,防御力越强,持续时间越长.', 66, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (15, '神圣战甲术', 309, 2, 9, 1, 28, 40, 120, 30, 50, 10, 5, 25, 27, 29, 700, 800, 900, 70, '通过运气,短时间提高对外部物理攻击的防御力,修炼等级越高,防御力提高持续时间越长.', 66, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (16, '困魔咒', 310, 2, 9, 1, 30, 10, 20, 10, 20, 15, 10, 27, 29, 31, 800, 900, 1000, 100, '使用护身符,在一定的空间范围内使用道力锁住其中敌人的技能,修炼等级越高,效果持续时间越长.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (17, '召唤骷髅', 332, 2, 10, 3, 32, 0, 0, 0, 0, 15, 10, 17, 19, 21, 400, 500, 600, 200, '在护身符中注入神气,召唤具有强大力量的灵魂为自己所用,修炼等级越高,可以召唤越强大的灵魂.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (18, '隐身术', 305, 2, 9, 1, 34, 5, 15, 5, 10, 5, 5, 20, 22, 24, 500, 600, 700, 70, '可以暂时在敌人面前隐身的技能,修炼等级越高,隐身效果持续时间越长.', 125, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (19, '集体隐身术', 307, 2, 9, 1, 36, 5, 15, 5, 10, 10, 5, 23, 25, 27, 600, 700, 800, 70, '升级版的隐身术,可以使一定区域内(3*3)的人全部隐身.修炼等级越高,隐身效果持续时间越长.', 125, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (20, '诱惑之光', 206, 1, 10, 1, 38, 0, 0, 0, 0, 3, 3, 13, 15, 17, 200, 300, 400, 60, '用强烈的电击麻痹敌人的灵魂,使之成为自己的帮手,修炼等级提升,持续时间和成功率越高.', 125, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (21, '瞬息移动', 207, 1, 10, 1, 40, 0, 0, 0, 0, 10, 10, 14, 16, 18, 300, 400, 500, 1200, '用强烈的技能贯通时空,随机移动到某一地点.修炼等级越高,成功率越高.', 186, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (22, '火墙', 216, 1, 4, 1, 42, 2, 9, 3, 18, 22, 30, 24, 26, 28, 600, 700, 800, 100, '一定的时间内在指定地方点燃火焰连续攻击此处敌人的技能,修炼等级提升,持续时间和威力将增加.', 126, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (23, '爆裂火焰', 220, 1, 4, 1, 44, 14, 18, 14, 18, 15, 20, 32, 34, 36, 1000, 1100, 1200, 90, '攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 246, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (24, '地狱雷光', 221, 1, 6, 1, 46, 14, 18, 14, 18, 17, 20, 33, 35, 37, 1000, 1100, 1200, 90, '用雷攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 126, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (25, '半月弯刀', 104, 0, 3, 3, 48, 20, 20, 30, 30, 0, 9, 24, 26, 28, 600, 700, 800, 0, '用快速挥动剑时产生的剑风攻击周围敌群(4个)的高级剑术,修炼等级越高,破坏力越大.', 66, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (26, '烈火剑法', 106, 0, 1, 1, 50, 100, 100, 150, 150, 2, 7, 32, 34, 36, 1000, 1100, 1200, 10000, '聚集体内热气注入到武器而加强破坏力,修炼等级越高,破坏力越大.', 126, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (27, '野蛮冲撞', 105, 0, 1, 1, 52, 3, 3, 2, 3, 20, 0, 27, 29, 31, 700, 800, 900, 3000, '是用肩部把等级低于自己的敌人撞开的武功,随修炼等级提升,增加撞开的距离和敌人的数量.', 186, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (29, '群体治愈术', 313, 2, 8, 1, 56, 8, 12, 4, 4, 10, 20, 31, 33, 35, 1000, 1100, 1200, 40, '可以治疗一定区域内(3*3)的人,修炼等级越高,体力恢复量就越多.', 5, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (30, '召唤神兽', 333, 2, 10, 3, 58, 0, 0, 0, 0, 15, 15, 30, 32, 34, 900, 1000, 1100, 200, '在护身符里注入神气,召唤神圣动物的技能,修炼等级越高,可以召唤越强的神兽.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (31, '魔法盾', 219, 1, 7, 1, 60, 0, 10, 0, 10, 20, 30, 29, 31, 33, 900, 1000, 1100, 0, '用魔力在自己周围形成保护膜,在一定时间内减少伤害的技能.修炼等级越高,持续时间越长.', 246, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (32, '圣言术', 217, 1, 10, 1, 62, 12, 16, 14, 18, 30, 30, 26, 28, 30, 700, 800, 900, 100, '是可以将死者系列的敌人一次性消灭的技能,修炼等级越高,成功率越高.', 125, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (33, '冰咆哮', 222, 1, 5, 1, 64, 12, 16, 14, 18, 19, 20, 34, 36, 38, 1000, 1100, 1200, 90, '用寒气攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 126, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (34, '莲月剑法', 108, 0, 1, 1, 66, 320, 320, 170, 170, 3, 9, 38, 40, 42, 1000, 1100, 1200, 10000, '用快速的剑法连续攻击两次的技能,修炼等级越高,破坏力越大.', 126, 334, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (35, '翔空剑法', 107, 0, 1, 1, 68, 100, 100, 125, 125, 2, 8, 35, 37, 39, 1000, 1100, 1200, 10000, '运气丹田喷向空中,在从半空落下攻击敌人的技能,修炼等级越高,破坏力越大.', 66, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (36, '空拳刀法', 311, 2, 11, 1, 70, 3, 3, 3, 3, 20, 10, 28, 30, 32, 900, 1000, 1100, 80, '用脚大力推开对方的技能,修炼等级越高,可以推开的概率和杀伤力越大.', 246, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (37, '月魂断玉', 304, 2, 8, 1, 72, 6, 10, 3, 3, 6, 3, 14, 16, 18, 300, 400, 500, 0, '将神圣气息凝聚在手中攻击敌人,佩戴神圣护身符使用威力更强.修炼等级越高,威力越强.', 126, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (38, '月魂灵波', 308, 2, 8, 1, 74, 8, 12, 7, 7, 8, 4, 24, 26, 28, 600, 700, 800, 0, '比月魂断玉更加强大的技能,修炼等级越高越强大.如果使用神圣护身符,威力更大.', 126, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (39, '冰月神掌', 203, 1, 5, 1, 76, 4, 8, 0, 4, 4, 1, 9, 11, 13, 100, 200, 300, 50, '冰系列的最基本技能,将敌人冻僵使对方行动变得缓慢,修炼等级越高,威力越强.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (40, '冰月震天', 210, 1, 5, 1, 78, 13, 17, 7, 11, 7, 6, 17, 19, 21, 400, 500, 600, 0, '冰月神掌的强化技能,修炼等级越高,威力越强.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (41, '霹雳掌', 202, 1, 6, 1, 80, 6, 10, 0, 4, 4, 1, 8, 10, 12, 100, 200, 300, 50, '雷系列最基本的技能,修炼等级越高,威力越强.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (53, '冰沙掌', 214, 1, 5, 1, 104, 12, 16, 12, 16, 12, 15, 22, 24, 26, 500, 600, 700, 80, '施放直线冰气攻击敌人的技能,还会一定时间内使敌人动作迟钝.修炼等级越高,威力越强.', 126, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (67, '风掌', 204, 1, 7, 1, 132, 5, 9, 0, 4, 3, 1, 10, 12, 14, 100, 200, 300, 50, '风系列最基本的技能,有将敌人推开的效果.修炼等级越高,威力越强,成功率越高.', 5, 8, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (72, '龙卷风', 223, 1, 7, 1, 142, 13, 17, 14, 18, 18, 20, 35, 37, 39, 1000, 1100, 1200, 0, '用龙卷风攻击指定(3*3)范围内所有敌人的技能,修炼等级越高,威力越强.', 126, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (73, '风震天', 215, 1, 7, 1, 144, 13, 17, 12, 16, 13, 15, 23, 25, 27, 600, 700, 800, 80, '施放直线风力攻击多数敌人的技能,修炼等级越高,威力越强.', 126, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (74, '击风', 211, 1, 7, 1, 146, 14, 18, 7, 11, 6, 6, 18, 20, 22, 400, 500, 600, 80, '用龙卷风攻击一名敌人的技能,修炼等级越高,威力越强.', 5, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (77, '回生术', 315, 2, 8, 1, 152, 15, 30, 10, 20, 100, 100, 35, 37, 39, 500, 600, 700, 500, '使用灵魂护身符让死人复活的技能,修炼等级越高,可以使死人复活的概率越高.', 5, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (89, '强魔震法', 312, 2, 9, 1, 178, 40, 120, 30, 50, 10, 5, 29, 31, 33, 900, 1000, 1100, 70, '使用护身符提高自己或他人的技能攻击力,或用元素护身符在一定时间内增加攻击元素的技能.修炼等级越高,效果持续时间越长.', 66, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (94, '猛虎强势', 314, 2, 9, 1, 186, 40, 120, 30, 50, 10, 5, 34, 36, 38, 1000, 1100, 1200, 70, '通过运气,暂时提高物理攻击力,修炼等级提升,攻击力增加量和持续时间也相应增多加长.', 66, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (102, '铁布衫', 111, 0, 1, 1, 202, 40, 90, 90, 30, 40, 20, 44, 47, 50, 6000, 9000, 18000, 0, '降低自己的破坏力来提高防御力和技能防御力的技能,随修炼等级提升,防御力和技能防御力的增加量和持续时间将增加.', 186, 334, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (103, '十方斩', 109, 0, 3, 3, 204, 20, 30, 20, 30, 7, 8, 40, 43, 46, 2000, 3000, 6000, 0, '用剑光攻击包围自己的所有敌人的技能,修炼等级越高,破坏力越大.', 66, 334, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (104, '移形换位', 218, 1, 10, 1, 206, 0, 0, 0, 0, 20, 20, 27, 29, 31, 800, 900, 1000, 0, '在一定空间内根据自己的意愿移动的技能,修炼等级越高,成功率越高.', 186, 74, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (105, '超强召唤骷髅', 334, 2, 10, 3, 208, 0, 0, 0, 0, 20, 25, 33, 35, 37, 1000, 1100, 1200, 200, '在护身符中注入神气,召唤带有强大力量的灵魂为自己所用,已经召唤了神兽或骷髅的状态下也可以使用.修炼等级越高,可以召唤越强大的灵魂.', 5, 138, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (106, '破血狂杀', 113, 0, 1, 1, 210, 90, 90, 30, 30, 100, 50, 48, 51, 54, 10000, 15000, 30000, 0, '降低自己的防御力暂时提高破坏力的技能,随修炼等级提升,破坏力和持续时间将增加.', 186, 464, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (107, '乾坤大挪移', 110, 0, 1, 1, 212, 0, 0, 0, 0, 30, 20, 42, 45, 48, 4000, 6000, 12000, 5000, '与对方互相换位置的技能,修炼等级越高,成功率越高.', 186, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (108, '斗转星移', 112, 0, 1, 1, 214, 0, 0, 0, 0, 30, 20, 46, 49, 52, 8000, 12000, 24000, 5000, '将远处的敌人吸到自己跟前的技能,修炼等级越高,成功率越高.', 186, 399, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (109, '君临步', 120, 0, 0, 1, 216, 3, 3, 3, 3, 50, 0, 50, 53, 56, 10000, 15000, 30000, 0, '以浑身之气击退敌人的技能,被击中后一定时间内处于头晕状态.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (110, '魄冰刺', 224, 1, 5, 1, 218, 16, 22, 16, 20, 30, 30, 38, 41, 44, 1000, 1500, 3000, 10, '施放三股寒气给大范围内敌人造成伤害,并且使对方行动变缓的技能.修炼等级越高,威力越强.', 246, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (111, '怒神霹雳', 225, 1, 6, 1, 220, 20, 40, 20, 30, 40, 40, 40, 42, 44, 2000, 3000, 6000, 10, '可以对大范围的(9*9)敌人进行雷电攻击,但距离越远杀伤力越小.修炼等级越高,威力越强.', 126, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (112, '凝血离魂', 227, 1, 10, 1, 222, 8, 5, 5, 5, 50, 100, 46, 48, 50, 8000, 12000, 24000, 0, '在一定时间内削弱大量体力而提高魔力的技能,修炼等级越高,单次提高魔力幅度越大.', 125, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (113, '焰天火雨', 226, 1, 4, 1, 224, 15, 19, 16, 24, 40, 40, 43, 45, 47, 5000, 7500, 15000, 10, '可以给一定区域内多数敌人带来火焰伤害.修炼等级越高,威力越强,可以攻击更多敌人.', 5, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (114, '旋风墙', 228, 1, 0, 1, 226, 4, 16, 3, 12, 30, 40, 49, 51, 53, 10000, 15000, 30000, 0, '在(3*3)范围内形成旋风的武功,随修炼等级提升,旋风墙的破坏力和持续时间会增加.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (120, '云寂术', 316, 2, 8, 1, 238, 20, 30, 10, 15, 18, 22, 38, 41, 44, 1000, 1500, 3000, 10, '可以消除技能和物理攻击效果,不仅可以取消中毒麻痹,还可以取消能力值提高效果.', 246, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (121, '妙影无踪', 317, 2, 9, 1, 240, 10, 15, 5, 5, 40, 40, 43, 45, 47, 5000, 7500, 15000, 0, '不仅对怪物隐身,对他人也可以隐身,修炼等级越高,隐身持续时间越长.', 125, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (122, '阴阳法环', 318, 2, 8, 1, 242, 30, 30, 30, 30, 30, 40, 46, 48, 50, 8000, 12000, 24000, 0, '调出体内潜在的力量,受到超过体力值的伤害时,可以抵御进攻并恢复少量体力值.', 246, 269, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (123, '移花接玉', 335, 2, 10, 1, 244, 20, 20, 20, 20, 15, 15, 40, 42, 44, 2000, 3000, 6000, 20, '牺牲自身的破坏力,提高属下怪物一定时间内的攻击力,修炼等级越高,属下怪物攻击力提高量越大.', 5, 204, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (124, '灭魂火符', 321, 2, 0, 1, 246, 12, 20, 8, 8, 18, 10, 49, 51, 53, 10000, 15000, 30000, 0, '灵魂火符的加强武功,每次发出3张护身符给予敌人更大的伤害.使用暗黑护身符会提高武功的威力.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (125, '横扫千军', 324, 2, 0, 1, 248, 10, 10, 10, 10, 10, 10, 54, 59, 64, 10000, 18000, 32000, 10, '用腿攻击敌人时,被击中的敌人不会受到伤害.但周围的敌人会受到较大的伤害或被击退.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (126, '移花接木', 117, 0, 0, 1, 250, 40, 40, 35, 35, 10, 10, 53, 58, 63, 10000, 18000, 32000, 100, '把所受到的部分伤害返还给攻击方的技能.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (127, '分身术', 237, 1, 0, 1, 252, 10, 10, 10, 10, 16, 24, 56, 61, 66, 10000, 18000, 32000, 0, '产生与自己同样的幻影,幻影可以施放与自己同样的魔法攻击.使用此技能必须要持有魔法矿石.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (128, '金刚之躯', 116, 0, 0, 1, 254, 10, 10, 10, 10, 40, 20, 51, 55, 59, 10000, 18000, 32000, 800, '利用浑身之气,回避中毒及异常状态.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (129, '养生术', 319, 2, 0, 2, 256, 11, 15, 0, 0, 7, 2, 47, 53, 60, 10000, 18000, 32000, 40, '每使用一次治愈术时,会恢复较多的HP.角色等级和灵魂系HP的恢复量.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (130, '泰山压顶', 118, 0, 0, 1, 258, 700, 700, 500, 500, 55, 35, 56, 61, 67, 20000, 30000, 40000, 200, '利用浑身之气减弱敌人的移动能力.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (131, '快刀斩马', 114, 0, 0, 1, 260, 100, 100, 150, 150, 80, 50, 52, 57, 65, 12000, 16000, 32000, 200, '把剑气集中在刀尖,瞬间击退多数敌人.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (132, '运气术', 101, 0, 0, 2, 262, 15, 15, 10, 10, 40, 20, 47, 50, 53, 10000, 20000, 40000, 800, '可以提高使用药水的能力,随着修炼等级的提升增加恢复量.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (133, '天打雷劈', 229, 1, 0, 2, 264, 0, 0, 0, 0, 20, 30, 52, 57, 62, 20000, 30000, 50000, 20, '自动向对自己发动攻击的敌人进行闪电攻击.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (134, '电闪雷鸣', 230, 1, 0, 1, 266, 14, 18, 14, 18, 17, 20, 54, 59, 64, 15000, 20000, 30000, 90, '施放时在一定范围内降闪电, 但闪电的掉落位置无法控制,攻击会造成非常大的伤害.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (135, '施毒大法', 322, 2, 0, 1, 268, 9, 9, 3, 3, 100, 35, 50, 54, 58, 30000, 33000, 36000, 500, '给一定范围内的怪物施毒.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (136, '吸星大法', 320, 2, 0, 1, 270, 60, 60, 30, 30, 18, 10, 48, 55, 62, 10000, 18000, 32000, 100, '把敌人受到的部分伤害值转化为HP,并加到自己或同伴身上.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (137, '迷魂大法', 323, 2, 0, 1, 272, 20, 20, 10, 10, 50, 15, 52, 56, 61, 10000, 15000, 25000, 200, '受到攻击的敌人变成稻草人,攻击稻草人所产生的部分伤害会转到敌人身上.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (153, '焰魔召唤术', 336, 2, 0, 3, 304, 10, 15, 10, 15, 30, 20, 50, 54, 56, 7000, 9000, 11000, 0, '解开并召唤被封印的焰魔,它的邪恶气息仍未消失.修炼级别越高,召唤的焰魔越强.', 0, 0, 0, '0001-01-01 00:00:00.000000');
INSERT INTO `magicinfo` VALUES (154, '魔焰强解术', 337, 2, 0, 1, 306, 10, 15, 10, 15, 80, 100, 52, 56, 58, 5500, 6500, 8500, 100, '把使用焰魔召唤术召唤的宝宝强制性解放的技能,宝宝的等级和体力越高,给对方的伤害越大.', 0, 0, 0, '0001-01-01 00:00:00.000000');
